(window.__quranSurahs=window.__quranSurahs||{})[96]={"nomPhon":"Al-Alaq","versets":{"1":{"text":"Lis, au nom de ton Seigneur qui a créé,","arabe":"ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ"},"2":{"text":"qui a créé l'homme d'une adhérence.","arabe":"خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ"},"3":{"text":"Lis! Ton Seigneur est le Très Noble,","arabe":"ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ"},"4":{"text":"qui a enseigné par la plume [le calame],","arabe":"ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ"},"5":{"text":"a enseigné à l'homme ce qu'il ne savait pas.","arabe":"عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ"},"6":{"text":"Prenez-garde! Vraiment l'homme devient rebelle,","arabe":"كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ"},"7":{"text":"dès qu'il estime qu'il peut se suffire à lui-même (à cause de sa richesse).","arabe":"أَن رَّءَاهُ ٱسْتَغْنَىٰٓ"},"8":{"text":"Mais, c'est vers ton Seigneur qu'est le retour.","arabe":"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ"},"9":{"text":"As-tu vu celui qui interdit","arabe":"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ"},"10":{"text":"à un serviteur d'Allah [Muhammad] de célébrer la Salât?","arabe":"عَبْدًا إِذَا صَلَّىٰٓ"},"11":{"text":"Vois-tu s'il est sur la bonne voie,","arabe":"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ"},"12":{"text":"ou s'il ordonne la piété?","arabe":"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ"},"13":{"text":"Vois-tu s'il dément et tourne le dos?","arabe":"أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ"},"14":{"text":"Ne sait-il pas que vraiment Allah voit?","arabe":"أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ"},"15":{"text":"Mais non! S'il ne cesse pas, Nous le saisirons certes, par le toupet,","arabe":"كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ"},"16":{"text":"le toupet d'un menteur, d'un pécheur.","arabe":"نَاصِيَةٍۢ كَٰذِبَةٍ خَاطِئَةٍۢ"},"17":{"text":"Qu'il appelle donc son assemblée.","arabe":"فَلْيَدْعُ نَادِيَهُۥ"},"18":{"text":"Nous appellerons les gardiens [de l'Enfer].","arabe":"سَنَدْعُ ٱلزَّبَانِيَةَ"},"19":{"text":"Non! Ne lui obéis pas; mais prosterne-toi et rapproche-toi.","arabe":"كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩"}}};